import{_ as e,a as d,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"德州扑克规则学习笔记","description":"德州扑克下注、牌型、边池和术语学习记录","frontmatter":{"title":"德州扑克规则学习笔记","description":"德州扑克下注、牌型、边池和术语学习记录","sources":[{"repository":"jekyall_blog","file":"_posts/Cc/Left/2023-06-19-TexasPoker.md","date":"Mon Jun 19 2023 12:48:54 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"生活记录","scope":"historical","audience":"general","group":"学习与记录","summary":"德州扑克下注、牌型、边池和术语学习记录","status":"active","related":[{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"},{"title":"阿甘正传","link":"/life/personal/media/movies/forrest-gump","kind":"影视导读","scope":"general","audience":"general"},{"title":"把《周易》读进具体问题：乾坤、泰否、既济未济对读","link":"/life/personal/yijing/reading-practice","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"狼人杀主持与角色笔记","link":"/life/personal/reading-games/werewolf-killing"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"狼人杀主持与角色笔记","link":"/life/personal/reading-games/werewolf-killing"},"next":false},"headers":[],"relativePath":"life/personal/reading-games/texaspoker.md","filePath":"life/personal/reading-games/texaspoker.md"}'),l={name:"life/personal/reading-games/texaspoker.md"};function i(n,t,o,s,h,p){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="德州扑克规则学习笔记" tabindex="-1">德州扑克规则学习笔记 <a class="header-anchor" href="#德州扑克规则学习笔记" aria-label="Permalink to &quot;德州扑克规则学习笔记&quot;">​</a></h1><p><span id="texaspoker"></span></p><blockquote><p>来源个人学习记录，本页按常见无限注德州学习口径纠正下注顺序、边池资格和比牌；赛事的不足额全下重开下注等细则仍须另查规则。</p></blockquote><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h2><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><blockquote><p>德州扑克是一种广泛玩的扑克牌游戏，通常由 2 至 10 名玩家参与。以下是德州扑克的基本规则：</p></blockquote><table tabindex="0"><thead><tr><th>步骤</th><th>描述</th></tr></thead><tbody><tr><td>1. 发底牌 (Hole Cards)</td><td>每名玩家收到两张私有底牌，只有自己能看见。</td></tr><tr><td>2. 小盲注和大盲注 (Small Blind and Big Blind)</td><td>两名玩家下小盲注和大盲注，小盲注通常是大盲注的一半。</td></tr><tr><td>3. 第一轮下注 (Pre-flop)</td><td>从大盲注左侧首位未弃牌且可行动者开始，按顺时针轮流行动；两人单挑时按钮小盲先行动。</td></tr><tr><td>4. 翻牌 (Flop)</td><td>庄家翻开三张公共牌，放在牌桌中央。</td></tr><tr><td>5. 第二轮下注 (Post-flop)</td><td>玩家继续下注轮次，可选择跟注、加注、弃牌或全下。</td></tr><tr><td>6. 转牌 (Turn)</td><td>庄家翻开第四张公共牌，放在牌桌中央。</td></tr><tr><td>7. 第三轮下注 (Post-turn)</td><td>玩家再次下注，可选择跟注、加注、弃牌或全下。</td></tr><tr><td>8. 河牌 (River)</td><td>庄家翻开第五张公共牌，放在牌桌中央。</td></tr><tr><td>9. 最后一轮下注 (Post-river)</td><td>玩家进行最后一轮下注，可选择跟注、加注、弃牌或全下。</td></tr><tr><td>10. 摊牌 (Showdown)</td><td>玩家亮出手牌，比较牌的强弱，胜出者获得底池。</td></tr><tr><td>11. 颁发奖金</td><td>奖金分配给胜出的玩家，根据牌型的强弱分配。</td></tr><tr><td>12. 开始新一轮游戏</td><td>游戏进入下一轮，庄家位置和盲注位置继续移动。</td></tr></tbody></table><h2 id="牌值大小" tabindex="-1">牌值大小 <a class="header-anchor" href="#牌值大小" aria-label="Permalink to &quot;牌值大小&quot;">​</a></h2><blockquote><p>A2345（也称为&quot;轮&quot;或&quot;小顺子&quot;）通常被视为最低的顺子</p></blockquote><table tabindex="0"><thead><tr><th>牌型</th><th>描述</th></tr></thead><tbody><tr><td>同花大顺 (Royal Flush)</td><td>同花色的 A、K、Q、J、10，最高的牌型。</td></tr><tr><td>同花顺 (Straight Flush)</td><td>同一花色的五张连续牌，例如：9、8、7、6、5。</td></tr><tr><td>四条 (Four of a Kind)</td><td>四张同样点数的牌；四条相同时还要比较第五张踢脚牌。</td></tr><tr><td>葫芦 (Full House)</td><td>三张同样点数的牌加一对，例如：K、K、K、5、5。</td></tr><tr><td>同花 (Flush)</td><td>五张同一花色的牌，不需要连续。</td></tr><tr><td>顺子 (Straight)</td><td>五张连续点数的牌，不需要同花色。</td></tr><tr><td>三条 (Three of a Kind)</td><td>三张同样点数的牌，另外两张不同点数的牌。</td></tr><tr><td>两对 (Two Pair)</td><td>两对不同点数的牌，例如：Q、Q、7、7、2。</td></tr><tr><td>一对 (One Pair)</td><td>一对相同点数的牌，另外三张不同点数的牌。</td></tr><tr><td>高牌 (High Card)</td><td>没有形成上述任何牌型的情况下，由最高点数的牌决定胜负。</td></tr></tbody></table><h2 id="边池" tabindex="-1">边池 <a class="header-anchor" href="#边池" aria-label="Permalink to &quot;边池&quot;">​</a></h2><p>底池按每人累计投入分层计算；是否全下不是争夺边池的唯一资格。弃牌者的投入留在池中，但失去争夺资格；仍持牌者只能争夺自己已匹配投入的层。无人跟注的超额部分应退回，不单独形成可赢的边池。</p><p>例如三人都未弃牌，A全下50，B与C各投入120：主池为50×3=150，三人均有资格；边池为(120−50)×2=140，仅B、C有资格。A牌最好也只能赢主池。若C只投入100，B多出的20无人匹配，应退回B，边池改为(100−50)×2=100。</p><p>筹码层由投入金额决定，不由全下的先后顺序决定。每一池分别在有资格且未弃牌的玩家中比较最佳五张牌；并列时分池，零头按适用赛事规则处理。参见 <a href="https://www.pokerstars.com/poker/games/rules/" target="_blank" rel="noopener noreferrer">PokerStars 底池与全下规则</a>。</p><h2 id="牌力" tabindex="-1">牌力 <a class="header-anchor" href="#牌力" aria-label="Permalink to &quot;牌力&quot;">​</a></h2><p>下表是从52张牌无放回抽取5张的组合分类，总数为 C(52,5)=2,598,960；不是德州7选5的分布，也不是某手底牌的获胜概率。占比为小数四舍五入，罕见牌型显示0.0000不代表概率为零。</p><table tabindex="0"><thead><tr><th style="text-align:left;">CardType</th><th style="text-align:left;">Number</th><th style="text-align:left;">占比</th></tr></thead><tbody><tr><td style="text-align:left;">高牌</td><td style="text-align:left;">1302540</td><td style="text-align:left;">0.5012</td></tr><tr><td style="text-align:left;">一对</td><td style="text-align:left;">1098240</td><td style="text-align:left;">0.4227</td></tr><tr><td style="text-align:left;">两对</td><td style="text-align:left;">123552</td><td style="text-align:left;">0.0475</td></tr><tr><td style="text-align:left;">三条</td><td style="text-align:left;">54912</td><td style="text-align:left;">0.0211</td></tr><tr><td style="text-align:left;">顺子</td><td style="text-align:left;">10200</td><td style="text-align:left;">0.0039</td></tr><tr><td style="text-align:left;">同花</td><td style="text-align:left;">5108</td><td style="text-align:left;">0.0020</td></tr><tr><td style="text-align:left;">葫芦</td><td style="text-align:left;">3744</td><td style="text-align:left;">0.0014</td></tr><tr><td style="text-align:left;">四条</td><td style="text-align:left;">624</td><td style="text-align:left;">0.0002</td></tr><tr><td style="text-align:left;">同花顺</td><td style="text-align:left;">36</td><td style="text-align:left;">0.0000</td></tr><tr><td style="text-align:left;">皇家同花顺</td><td style="text-align:left;">4</td><td style="text-align:left;">0.0000</td></tr></tbody></table><h2 id="加注规则" tabindex="-1">加注规则 <a class="header-anchor" href="#加注规则" aria-label="Permalink to &quot;加注规则&quot;">​</a></h2><ol><li><strong>最低下注与加注：</strong> 常见无限注德州首次最低下注为一个大盲注；加注增量至少等于本轮前一次完整下注或完整加注的增量。例如大盲2，某人加到6（增加4），下一次完整加注至少到10，不能只再加2。</li><li><strong>全下：</strong> 可以投入自己剩余的全部筹码；金额不足完整加注时，是否为已行动者重新开放加注，须按所用规则判断。全下后不能继续投入，能赢的池仍受已投入金额限制。</li><li><strong>回合结束：</strong> 未弃牌且仍有筹码者都完成行动、匹配本轮投入后结束下注；已经全下者不必补到相同额度。若其余人均弃牌，最后持牌者无需摊牌即可赢池。</li><li><strong>下注结构：</strong> 固定限注、底池限注和无限注的额度不同；“无限注”仍有最低加注与自己筹码总量限制，并非任意金额都合法。</li></ol><p>规则说明：<a href="https://www.pokerstars.com/poker/games/texas-holdem/" target="_blank" rel="noopener noreferrer">无限注、固定限注与底池限注</a>。</p><h2 id="术语" tabindex="-1">术语 <a class="header-anchor" href="#术语" aria-label="Permalink to &quot;术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>解释</th></tr></thead><tbody><tr><td>底牌 (Hole Cards)</td><td>玩家手中的两张私有牌，只有自己能看见。</td></tr><tr><td>底池 (Pot)</td><td>所有下注的筹码总额，作为奖金的来源。</td></tr><tr><td>小盲注 (Small Blind)</td><td>通常由按钮左侧玩家投入的强制注，常为大盲注一半；单挑由按钮位投入。</td></tr><tr><td>大盲注 (Big Blind)</td><td>通常由小盲左侧玩家投入的强制注；数额由局级或赛事规定，不按底池计算。</td></tr><tr><td>庄家 (Dealer)</td><td>按钮表示本手的名义庄家位置；实体发牌员不一定是按钮位玩家。</td></tr><tr><td>加注 (Raise)</td><td>在当前下注额度的基础上增加下注。</td></tr><tr><td>跟注 (Call)</td><td>与前一玩家的下注额度相同。</td></tr><tr><td>弃牌 (Fold)</td><td>放弃当前手牌，退出这一回合。</td></tr><tr><td>全下 (All-In)</td><td>下注所有筹码，无法再进行下注，但有资格赢得部分底池。</td></tr><tr><td>翻牌 (Flop)</td><td>游戏开始后，发出的前三张公共牌。</td></tr><tr><td>转牌 (Turn)</td><td>游戏继续后，翻出的第四张公共牌。</td></tr><tr><td>河牌 (River)</td><td>游戏继续后，翻出的第五张公共牌。</td></tr><tr><td>满堂红 (Full House)</td><td>一对加上三条，例如：J、J、10、10、10。</td></tr><tr><td>三条 (Three of a Kind)</td><td>三张相同点数的牌。</td></tr><tr><td>葫芦 (Full House)</td><td>三条加上一对，例如：A、A、A、K、K。</td></tr><tr><td>同花 (Flush)</td><td>五张同一花色的牌，不需要连续。</td></tr><tr><td>同花大顺 (Royal Flush)</td><td>同花色的 A、K、Q、J、10，最高的牌型。</td></tr><tr><td>大翻盘 (Bad Beat)</td><td>一手在领先的情况下输掉，通常是因为运气不佳的情况。</td></tr></tbody></table><h2 id="踢脚牌" tabindex="-1">踢脚牌 <a class="header-anchor" href="#踢脚牌" aria-label="Permalink to &quot;踢脚牌&quot;">​</a></h2><p>在德州扑克中，&quot;踢脚牌&quot;（Kicker）是一种用来决定在出现相同牌型时，哪一手牌更强的辅助牌。当多名玩家都拥有相同牌型时，通常会比较他们的踢脚牌来决定胜负。</p><p>先比对子点数，再比踢脚牌：一对8胜一对7，这是对子本身较大。若两人同为一对8，最佳五张分别是8、8、A、Q、J与8、8、K、Q、J，才由第一张踢脚牌A大于K分胜负。比较必须使用两张底牌与五张公共牌中可选的最佳五张，不要求使用全部底牌。</p><p>牌型与同类比牌依据：<a href="https://www.pokerstars.com/poker/games/rules/hand-rankings/" target="_blank" rel="noopener noreferrer">PokerStars 牌型规则</a>。</p><p>踢脚牌在德州扑克中非常重要，因为它可以帮助区分相同牌型的不同强度。如果踢脚牌也相同，那么可能会出现平局，底池将平均分配给这些平局的玩家。</p>',27)])])}const u=e(l,[["render",i]]);export{f as __pageData,u as default};
